mapper.select:
select tfr.test_flow_run_id as testFlowRunId, tfr.test_flow_id as testFlowId, tfr.test_project_env_id as testProjectEnvId, tfr.run_scenario_id as runScenarioId, tfr.status as status, tfr.graph_json_snapshot as graphJsonSnapshot, tfr.flow_snapshot as flowSnapshot, tfr.run_execution_state as runExecutionState, tfr.paused_at as pausedAt, tfr.graph_fingerprint as graphFingerprint, tfr.started_at as startedAt, tfr.finished_at as finishedAt, tfr.duration_ms as durationMs, tfr.error_code as errorCode, tfr.error_message as errorMessage, tfr.trigger_type as triggerType, tfr.del_status as delStatus, tfr.create_time as createTime, tfr.update_time as updateTime from test_flow_run tfr where tfr.del_status = 0
and tfr.test_flow_id = #{testFlowId}
and tfr.test_project_env_id = #{testProjectEnvId}
and tfr.run_scenario_id = #{runScenarioId}
and tfr.status = #{status}
and tfr.graph_fingerprint = #{graphFingerprint}
and tfr.trigger_type = #{triggerType}
order by tfr.test_flow_run_id desc

select count(1)
from test_flow_run tfr
where tfr.del_status = 0

    and tfr.test_flow_id = #{testFlowId}


    and tfr.test_project_env_id = #{testProjectEnvId}


    and tfr.run_scenario_id = #{runScenarioId}


    and tfr.status = #{status}


    and tfr.graph_fingerprint = #{graphFingerprint}


    and tfr.trigger_type = #{triggerType}

select tfr.test_flow_run_id, tfr.test_flow_id, tfr.test_project_env_id, tfr.run_scenario_id, tfr.status, tfr.graph_json_snapshot, tfr.flow_snapshot, tfr.run_execution_state, tfr.paused_at, tfr.graph_fingerprint, tfr.started_at, tfr.finished_at, tfr.duration_ms, tfr.error_code, tfr.error_message, tfr.trigger_type, tfr.del_status, tfr.create_time, tfr.update_time from test_flow_run tfr where tfr.del_status = 0
and tfr.test_flow_id = #{testFlowId}
and tfr.test_project_env_id = #{testProjectEnvId}
and tfr.run_scenario_id = #{runScenarioId}
and tfr.status = #{status}
and tfr.graph_fingerprint = #{graphFingerprint}
and tfr.trigger_type = #{triggerType}
order by tfr.test_flow_run_id desc limit 1

mapper.update:
update test_flow_run
set status = 'running',
    update_time = #{updateTime}
where test_flow_run_id = #{testFlowRunId}
  and status = 'paused'
  and del_status = 0

update test_flow_run
set del_status = 1
where test_flow_run_id = #{testFlowRunId}
